/**
 * Localities of the national world: each is a 120×80 cell grid generated by the same
 * engine (terrain, roads, districts, landmarks, décor) so Lomé Life's level of detail is
 * the floor for every pole. Lomé keeps its original rules verbatim (the generated city is
 * byte-identical); other poles bring their own geography and visual identity.
 *
 * Positions on the national map come from the sourced boundaries
 * (`lib/haroolife/togo/boundaries.json`, geoBoundaries from OpenStreetMap, ODbL): a pole is
 * drawn at the centroid of its préfecture, never at a typed-in coordinate.
 *
 * Only one locality is active at a time (`current()`); switching it is how the player
 * travels. World caches are keyed by locality so a return trip costs nothing to rebuild.
 */
import { SIZE } from '../townsmen-engine'
import { hash } from './seed'
import type { DistrictDef, Landmark, Terrain } from './world'

export type LocalityId = 'lome' | 'kara'

export interface LocalityDecor {
  /** Ground colour per district (hex). */
  grass: Record<string, string>
  earth: string
  sand: string
  /** Inland water (lagoon or river) and open water (ocean or reservoir). */
  lagoon: string
  ocean: string
  hill: string
  /** Trees along avenues, on the shore row and in concessions. */
  streetTree: string
  shoreTree: string
  concessionTree: string
  /** Districts where concessions get palms rather than shade trees. */
  coastalDistricts: string[]
  /** Row of the shore road (beach boulevard), null inland. */
  shoreRow: number | null
  /** Sky tint at noon, for the atmosphere of the region. */
  sky: string
}

export interface LocalityDef {
  id: LocalityId
  name: string
  region: string
  /** Names as spelled in the sourced boundaries file. */
  geo: { region: string; prefecture: string }
  /** The player's 22×22 estate (Lomé only): where it sits, or null when visiting. */
  estate: { x0: number; y0: number; size: number } | null
  /** Arrival cell when travelling here: a road cell near the bus station. */
  gate: { x: number; y: number }
  /** Short line a resident would say about the town. */
  note: string
  terrain(x: number, y: number): Terrain
  /** Road network incl. bridges and the shore road; never asked outside the grid. */
  road(x: number, y: number): boolean
  districts: DistrictDef[]
  waterNames: { lagoon: string; ocean: string; sand: string }
  landmarks: Landmark[]
  decor: LocalityDecor
  /**
   * Industrial area (V3): filler plots there hold warehouses, tanks and containers instead of
   * houses. Scene data only: lot ids and positions do not change.
   */
  industry?: { x0: number; x1: number; y0: number; y1: number }
}

const W = 120
const H = 80
const within = (x: number, y: number) => x >= 0 && y >= 0 && x < W && y < H

