  x >= LOME_ESTATE.x0 &&
  y >= LOME_ESTATE.y0 &&
  x < LOME_ESTATE.x0 + LOME_ESTATE.size &&
  y < LOME_ESTATE.y0 + LOME_ESTATE.size

