/** The river's north bank row for a column: a winding band three cells wide. */
const karaBank = (x: number) => 56 + Math.round(Math.sin(x / 9) * 2 + Math.cos(x / 23))
function karaTerrain(x: number, y: number): Terrain {
  // Lama hills: the north-east corner and a ridge on the first rows.
  if (y < 3 && hash(x, 0, 31) > 0.35) return 'hill'
  if (x >= 100 && y < 12 && hash(x, y, 32) > 0.25) return 'hill'
  if (x >= 108 && y < 20) return 'hill'
  const bank = karaBank(x)
  if (y >= bank && y <= bank + 2) return 'lagoon'
  if (y === bank - 1 || y === bank + 3) return 'sand'
  // Reservoir (retenue) in the south-west corner.
  if (x < 14 && y >= 70 && hash(x, y, 33) > 0.2) return 'ocean'
  if (x < 16 && y >= 68 && y < 70 && hash(x, y, 34) > 0.6) return 'sand'
  return 'land'
}
const KARA_BRIDGES = new Set([36, 72, 108])
function karaRoad(x: number, y: number): boolean {
  const t = karaTerrain(x, y)
  if (t === 'ocean' || t === 'hill') return false
  if (t === 'lagoon' || t === 'sand') return KARA_BRIDGES.has(x) // bridges and their ramps only
  if (x % 12 === 0 || y % 10 === 0) return true
  const d = districtOf(KARA_DISTRICTS, x, y)
  if (d.density === 3 && (x % 12 === 6 || y % 10 === 5)) return true
  if (d.density === 2 && y % 10 === 5 && hash(Math.floor(x / 12), Math.floor(y / 10), 8) > 0.25)
    return true
  if (d.density === 1 && x % 12 === 6 && hash(Math.floor(x / 12), Math.floor(y / 10), 9) > 0.55)
    return true
  return false
}
